#!/usr/bin/env bash
# Evaluation v2: dual-protocol operating curves (ORACLE vs DEPLOYABLE),
# same held-out split for every method, overhead-inclusive costs.
set -e
if [ ! -d "src/tokenguard" ]; then echo "ERROR: run from TokenGuard repo root"; exit 1; fi
decode() { base64 -d > "$1"; echo "  wrote $1"; }
echo "Installing evaluation v2..."
decode "scripts/ntc_operating_curves.py" << 'B64EOF'

B64EOF
echo ""
echo "Installed. Run the primary evaluation across the six core settings."